export async function findLabelById(
  orgId: OrgId,
  labelId: LabelId,
): Promise<IssueLabel | null> {
  const row = getDb()
    .select()
    .from(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .get();
  return row ? toLabel(row) : null;
}

/**
 * Moves every issue from the source label onto the target, then deletes the
 * source. Returns the number of issues that carried the source label.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();
  const sourceRows = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();
  const issueIds = [...new Set(sourceRows.map((row) => row.issueId))];

  if (issueIds.length > 0) {
    const alreadyTarget = new Set(
      db
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, targetLabelId),
            inArray(issueLabels.issueId, issueIds),
          ),
        )
        .all()
        .map((row) => row.issueId),
    );
    const toAdd = issueIds.filter((id) => !alreadyTarget.has(id));
    if (toAdd.length > 0) {
      db.insert(issueLabels)
        .values(
          toAdd.map((issueId) => ({ orgId, issueId, labelId: targetLabelId })),
        )
        .run();
    }
  }

  await deleteLabel(orgId, sourceLabelId);
  return issueIds.length;
}
